import { PlaneGeometry, MeshBasicNodeMaterial, Group, Mesh } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.userData.cleanup = () => {};
  group.userData.handlers = {};

  // --- Resolve text content from config ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // --- Image plane ---
  const aspect = 512 / 320;
  const width = 4.0;
  const height = width / aspect;
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    color: 0x0b0b10,
    transparent: false,
    side: ctx.THREE.DoubleSide,
  });
  const plane = new Mesh(geometry, material);
  plane.position.z = -0.01;
  group.add(plane);

  // Load texture
  const loadTex = ctx.textureLoader.loadTexture(config.imageUrl);
  loadTex.then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
  });

  // --- Text content from config ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const fontSize = item.typography?.fontSize ?? 96;
    const textOpts = {
      fontSize,
      color: '#e8ecf2',
      align: 'center',
      maxWidthPx: width * 100,
    };
    const textObj = ctx.fontAtlas.createText(item.text, textOpts);
    textObj.position.set(0, 0, 0.01);
    group.add(textObj);
  }

  return group;
}
